+// Estándar de numeración (documentos fiscales): SSS-AAAA-NNNNNN. Un valor fuera de rango es error; nunca se trunca.
+function entreRango(valor, min, max, nombre) {
+  if (!Number.isInteger(valor) || valor < min || valor > max)
+    throw new RangeError(`${nombre} inválido: debe ser un entero de ${min} a ${max}`);
+  return valor;
+}
+
+export function numeroFactura(sucursal, gestion, correlativo) {
+  const s = entreRango(sucursal, 1, 999, "Sucursal");
+  const a = entreRango(gestion, 0, 9999, "Gestión");
+  const n = entreRango(correlativo, 1, 999999, "Correlativo");
+  return `${String(s).padStart(3, "0")}-${String(a).padStart(4, "0")}-${String(n).padStart(6, "0")}`;
+}
